/**
 * Mock Spine Runtime for Hexa Keno
 * Provides a minimal pixi_spine global for mascot animations
 * Uses the custom crystal-mascot.json skeleton
 */
(function () {
    'use strict';

    console.log('[Spine] Using Mock Runtime for Crystal Mascot');

    // Mock Spine class that wraps PIXI.Container
    class MockSpine extends PIXI.Container {
        constructor(data) {
            super();
            this.spineData = data;
            this.skeleton = { data: data };
            this.state = {
                timeScale: 1,
                tracks: [],
                listeners: [],

                setAnimation: (track, name, loop) => {
                    console.log('[Spine Mock] play:', name);
                    this.state.tracks[track] = { animation: { name }, loop };
                    this._setAnimState(name);
                    return { alpha: 1 };
                },

                addAnimation: (track, name, loop, delay) => {
                    console.log('[Spine Mock] queue:', name);
                    return { alpha: 1 };
                },

                addListener: (listener) => {
                    this.state.listeners.push(listener);
                },

                clearTracks: () => {
                    this.state.tracks = [];
                },

                setEmptyAnimation: (track, mixDuration) => { }
            };

            this.stateData = {
                setMix: (from, to, duration) => { }
            };

            // Animation state for visual feedback
            this._animState = 'idle';
            this._animFrame = 0;

            // Create visual placeholder
            this._createVisual();
        }

        _setAnimState(name) {
            this._animState = name;
            this._animFrame = 0;
        }

        _createVisual() {
            // Create a crystal mascot placeholder - much larger and more visible
            this._graphics = new PIXI.Graphics();
            this._drawMascot('idle');
            this.addChild(this._graphics);

            // Add floating animation
            this._startAnimation();
        }

        _drawMascot(state) {
            const g = this._graphics;
            g.clear();

            // Crystal body (larger)
            g.beginFill(0x00CED1, 0.9);
            g.moveTo(0, -100);       // Top point
            g.lineTo(60, -30);       // Top right
            g.lineTo(50, 60);        // Bottom right
            g.lineTo(-50, 60);       // Bottom left
            g.lineTo(-60, -30);      // Top left
            g.closePath();
            g.endFill();

            // Inner glow
            g.beginFill(0x40E0D0, 0.6);
            g.moveTo(0, -70);
            g.lineTo(40, -20);
            g.lineTo(35, 40);
            g.lineTo(-35, 40);
            g.lineTo(-40, -20);
            g.closePath();
            g.endFill();

            // Sparkles
            const sparklePos = state === 'run' ? [[0, -80], [30, -10], [-25, 20]] :
                state === 'jump' ? [[0, -90], [40, -20], [-30, 10], [0, 50]] :
                    [[0, -75], [25, -5], [-20, 25]];

            g.beginFill(0xFFFFFF, 0.95);
            sparklePos.forEach(([x, y]) => {
                const size = 4 + Math.random() * 4;
                g.drawCircle(x, y, size);
            });
            g.endFill();

            // Eyes (simple white dots)
            g.beginFill(0xFFFFFF, 1);
            const eyeY = state === 'jump' ? -25 : -20;
            g.drawCircle(-15, eyeY, 8);
            g.drawCircle(15, eyeY, 8);
            g.endFill();

            // Pupils
            g.beginFill(0x000000, 1);
            g.drawCircle(-15, eyeY + 2, 4);
            g.drawCircle(15, eyeY + 2, 4);
            g.endFill();

            // Mouth (smile)
            if (state === 'jump' || state === 'shoot') {
                g.beginFill(0xFFFFFF, 0.8);
                g.arc(0, 10, 15, 0, Math.PI);
                g.endFill();
            }
        }

        _startAnimation() {
            const animate = () => {
                if (this.destroyed) return; // Stop if destroyed

                this._animFrame++;

                // Floating motion
                const floatY = Math.sin(this._animFrame * 0.05) * 8;
                const floatRotation = Math.sin(this._animFrame * 0.03) * 0.05;

                if (this._graphics && !this._graphics.destroyed) {
                    this._graphics.y = floatY;
                    this._graphics.rotation = floatRotation;
                }

                // Redraw mascot with current state periodically
                if (this._animFrame % 30 === 0 && this._graphics && !this._graphics.destroyed) {
                    this._drawMascot(this._animState);
                }

                requestAnimationFrame(animate);
            };
            requestAnimationFrame(animate);
        }

        update(delta) {
            // Optional ticker update
        }

        static from(data, options = {}) {
            console.log('[Spine Mock] Creating Spine:', data);
            const spine = new MockSpine(data);
            if (options.scale) {
                spine.scale.set(options.scale);
            }
            return spine;
        }
    }

    // Expose global pixi_spine object
    window.pixi_spine = {
        Spine: MockSpine
    };
})();
